def _next_credential_status_receipt_consumption_cursor_locked(
    self, tenant_id: str
) -> int:
    """分配租户内下一个持久化凭证状态回执消费游标。

    正整数、按追加递增；游标空间租户内跨验证者共享，并与验真回执
    消费历史及其他历史游标空间完全独立。
    """
    cursor = (
        self._credential_status_receipt_consumption_cursors.get(
            tenant_id, 0
        )
        + 1
    )
    self._credential_status_receipt_consumption_cursors[
        tenant_id
    ] = cursor
    return cursor

def _append_credential_status_receipt_consumption_event_locked(
    self,
    tenant_id: str,
    verifier_did: str,
    nonce: str,
    receipt_id: str,
    consumed_at: str,
) -> None:
    """在锁内追加一条凭证状态回执消费历史事件。

    须与消费记录、审计事件同一次原子写落盘；cursor 为租户内跨验证
    者的持久递增正整数。
    """
    bucket = self._ensure_bucket_locked(tenant_id)
    bucket["credential_status_receipt_consumption_events"].append(
        {
            "cursor": (
                self
                ._next_credential_status_receipt_consumption_cursor_locked(
                    tenant_id
                )
            ),
            "receipt_id": receipt_id,
            "verifier_did": verifier_did,
            "nonce": nonce,
            "consumed_at": consumed_at,
        }
    )

def _backfill_credential_status_receipt_consumption_events_locked(
    self,
) -> None:
    """加载迁移：为缺消费历史的旧凭证状态回执消费记录稳定补录。

    对每个租户遍历已持久化的 consumed_credential_status_receipts，
    将尚无对应消费历史事件的记录按
    (consumed_at, verifier_did, nonce) 升序稳定补录，cursor 为该租
    户内新分配的持久化正整数。仅在内存中补录：随下一次原子写一并
    落盘；即使加载后无写操作，重启时也按相同顺序重建为相同 cursor。
    """
    for tenant_id in sorted(self._tenants):
        bucket = self._tenants[tenant_id]
        events = bucket.setdefault(
            "credential_status_receipt_consumption_events", []
        )
        existing = {
            (
                event.get("verifier_did"),
                event.get("nonce"),
            )
            for event in events
        }
        missing: List[Tuple[str, str, str, Dict[str, Any]]] = []
        for verifier_did, by_nonce in bucket.get(
            "consumed_credential_status_receipts", {}
        ).items():
            for nonce, row in by_nonce.items():
                if (verifier_did, nonce) in existing:
                    continue
                missing.append(
                    (
                        row.get("consumed_at") or "",
                        verifier_did,
                        nonce,
                        row,
                    )
                )
        missing.sort(key=lambda item: (item[0], item[1], item[2]))
        for _, verifier_did, nonce, row in missing:
            events.append(
                {
                    "cursor": (
                        self
                        ._next_credential_status_receipt_consumption_cursor_locked(
                            tenant_id
                        )
                    ),
                    "receipt_id": row.get("receipt_id", ""),
                    "verifier_did": verifier_did,
                    "nonce": nonce,
                    "consumed_at": row.get("consumed_at") or "",
                }
            )
        events.sort(key=lambda event: int(event.get("cursor", 0)))

def list_credential_status_receipt_consumptions(
    self,
    tenant_id: str,
    after: int = 0,
    limit: int = 50,
    verifier_did: Optional[str] = None,
) -> Tuple[List[CredentialStatusReceiptConsumptionEvent], int]:
    """只读分页查询本租户凭证状态回执消费历史事件。

    - 先按 verifier_did 精确过滤（未提供时不过滤）；
    - 再按 cursor > after 升序取至多 limit 项；
    - next_after 为本页末项 cursor，空页保持 after。
    纯只读：不修改任何状态、不记审计、不触发落盘。
    """
    with self._lock:
        bucket = self._bucket_locked(tenant_id)
        entries: List[Dict[str, Any]] = []
        if bucket is not None:
            entries = list(
                bucket.get(
                    "credential_status_receipt_consumption_events", []
                )
            )
        entries.sort(key=lambda event: int(event.get("cursor", 0)))
        picked: List[CredentialStatusReceiptConsumptionEvent] = []
        for row in entries:
            if (
                verifier_did is not None
                and row.get("verifier_did") != verifier_did
            ):
                continue
            cursor = int(row["cursor"])
            if cursor <= after:
                continue
            if len(picked) >= limit:
                break
            picked.append(
                CredentialStatusReceiptConsumptionEvent(
                    cursor=cursor,
                    receipt_id=row["receipt_id"],
                    verifier_did=row["verifier_did"],
                    nonce=row["nonce"],
                    consumed_at=row["consumed_at"],
                )
            )
        next_after = picked[-1].cursor if picked else after
        return picked, next_after

def export_credential_status_receipt_consumption_events(
    self,
    tenant_id: str,
    after: int = 0,
    limit: int = 1000,
    snapshot: Optional[int] = None,
) -> Tuple[List[CredentialStatusReceiptConsumptionEvent], int, int]:
    """只读快照导出本租户凭证状态回执消费历史（NDJSON 导出用）。

    - 在同一把锁内原子读取租户当前最大游标 max_cursor（无事件为 0，
      取本租户专属的凭证状态回执消费游标）；snapshot 缺省取该
      max_cursor，显式提供时须不超过 max_cursor，否则 ValidationError；
    - after 不得大于生效 snapshot，否则 ValidationError；
    - 取 after < cursor <= snapshot 按 cursor 升序至多 limit 项；
    - 返回 (事件列表, 生效快照, next_after)；next_after 为本页末项
      cursor，空页保持 after。
    纯只读：不修改任何状态、不分配游标、不记审计、不触发落盘。
    """
    with self._lock:
        max_cursor = (
            self._credential_status_receipt_consumption_cursors.get(
                tenant_id, 0
            )
        )
        if snapshot is None:
            effective_snapshot = max_cursor
        elif snapshot > max_cursor:
            raise ValidationError(
                "查询参数 snapshot 不得超过当前最大游标"
            )
        else:
            effective_snapshot = snapshot
        if after > effective_snapshot:
            raise ValidationError(
                "查询参数 after 不得大于 snapshot"
            )
        bucket = self._bucket_locked(tenant_id)
        entries: List[Dict[str, Any]] = []
        if bucket is not None:
            entries = list(
                bucket.get(
                    "credential_status_receipt_consumption_events", []
                )
            )
        entries.sort(key=lambda event: int(event.get("cursor", 0)))
        picked: List[CredentialStatusReceiptConsumptionEvent] = []
        for row in entries:
            cursor = int(row["cursor"])
            if cursor <= after or cursor > effective_snapshot:
                continue
            if len(picked) >= limit:
                break
            picked.append(
                CredentialStatusReceiptConsumptionEvent(
                    cursor=cursor,
                    receipt_id=row["receipt_id"],
                    verifier_did=row["verifier_did"],
                    nonce=row["nonce"],
                    consumed_at=row["consumed_at"],
                )
            )
        next_after = picked[-1].cursor if picked else after
        return picked, effective_snapshot, next_after

